class ScientificExecutionError(ValueError):
    """Bounded feedback from the scientist's isolated code, never a host traceback."""

    def __init__(self, receipt):
        super().__init__("isolated scientific computation did not succeed")
        self.public_details = {"status": receipt.get("status"), "execution_id": receipt.get("execution_id"),
            "scientific_negative": False,
            "returncode": receipt.get("returncode"),
            "reason": str(receipt.get("reason", ""))[:2048],
            "stdout": str(receipt.get("stdout", ""))[:65536],
            "stderr": str(receipt.get("stderr", ""))[:65536],
            "stdout_truncated": receipt.get("stdout_truncated"),
            "stderr_truncated": receipt.get("stderr_truncated")}
        # Host setup failures can contain filesystem paths; do not forward them.
        if receipt.get("status") in {"executor_error", "rejected"}:
            self.public_details.update(reason="Executor setup or snapshot rejected; operator must inspect its private receipt",
                                       stdout="", stderr="")


def encoded(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False)


def signature(value):
    return hashlib.sha256(encoded(value).encode()).hexdigest()


def validate_forecast(value, request):
    """Check meaning-bearing identities/units; null preserves justified abstention."""
    encoded(value)
    if not isinstance(value, dict) or not isinstance(value.get("predictions"), list):
        raise TypeError("forecast must return an object with a predictions list")
    expected = [s["specimen_id"] for s in request["specimens"]]
    actual = [row.get("specimen_id") for row in value["predictions"]]
    if sorted(actual) != sorted(expected) or len(set(actual)) != len(actual):
        raise ValueError("forecast must cover each requested specimen exactly once")
    for row in value["predictions"]:
        quantities = {"density_g_cm3": "g/cm^3", "grain_size_nm": "nm"}
        quantities.update({k: u for k, u in {"grain_d90_nm": "nm",
            "coarse_number_fraction": "1", "porosity_area_fraction": "1"}.items() if k in row})
        if request.get("origin") in ("physical", "synthetic"):  # SDL-2 v1.2: virtual magnetic forecasts
            quantities.update({k: u for k, u in PHYSICAL_MAGNETIC_UNITS.items() if k in row})
        for name, unit in quantities.items():
            prediction = row.get(name)
            if not isinstance(prediction, dict) or prediction.get("unit") != unit:
                raise ValueError(f"{name} needs a prediction object and unit {unit}")
            if not isinstance(prediction.get("status"), str) or not prediction["status"]:
                raise ValueError(f"{name} needs an explicit status")
            for field in ("mean", "sd"):
                if field not in prediction:
                    raise ValueError(f"{name}.{field} is required (null means unknown)")
                number = prediction[field]
                if number is not None and (type(number) not in (int, float)
                                           or not math.isfinite(number) or number < 0):
                    raise ValueError(f"{name}.{field} must be finite, nonnegative or null")
            if prediction["mean"] is None and prediction["sd"] is not None:
                raise ValueError("an abstained mean cannot have a numerical standard deviation")
            if prediction["mean"] is None and not prediction.get("reason"):
                raise ValueError("an abstention needs a reason")
            if unit == "1" and prediction["mean"] is not None and prediction["mean"] > 1:
                raise ValueError("fraction forecast mean must be in [0,1]")
            if name == "coarse_number_fraction" and prediction["mean"] is not None:
                threshold = prediction.get("coarse_threshold_nm")
                if type(threshold) not in (int, float) or not math.isfinite(threshold) or threshold <= 0:
                    raise ValueError("coarse fraction needs an explicit positive coarse_threshold_nm")
    return value


def _spec(name, description, properties, required=()):
    return {"name": name, "description": description, "parameters": {
        "type": "object", "properties": properties, "required": list(required),
        "additionalProperties": False}}


