def runtime_identity():
    # Request validation, immutable storage, and imported scientific helpers are
    # part of the execution contract too, not only this controller and executor.
    package = Path(__file__).resolve().parents[1]
    sources = {p.relative_to(package).as_posix(): hashlib.sha256(p.read_bytes()).hexdigest()
               for p in sorted(package.rglob("*"))
               if p.is_file() and p.suffix in {".py", ".json", ".csv"}}
    return {"controller_sha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
            "executor_sha256": hashlib.sha256(Path(__file__).with_name("executor.py").read_bytes()).hexdigest(),
            "scientific_package_sha256": signature(sources),
            "science_image": IMAGE, "compute_resources": resource_policy()}


class Investigator:
    def __init__(self, campaign, directory, *, executor=execute, sources=None):
        self.campaign = campaign
        self.directory = Path(directory).resolve()
        validate_private_path(self.directory)
        self.directory.mkdir(parents=True, exist_ok=True, mode=0o700)
        self.executor = executor
        self.staged = self.directory / "staged"
        self.staged.mkdir(exist_ok=True)
        self.receipts = self.directory / "computations"
        self.db = sqlite3.connect(self.directory / "investigation.sqlite3", isolation_level=None)
        self.db.row_factory = sqlite3.Row
        self.db.execute("PRAGMA journal_mode=WAL")
        self.db.execute("PRAGMA synchronous=FULL")
        self.db.executescript("""
          CREATE TABLE IF NOT EXISTS calls(id TEXT PRIMARY KEY, signature TEXT NOT NULL,
            name TEXT NOT NULL, arguments TEXT NOT NULL, intent TEXT, result TEXT);
          CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY, value TEXT NOT NULL);
        """)
        runtime = encoded(runtime_identity())
        old_runtime = self.db.execute("SELECT value FROM meta WHERE key='runtime'").fetchone()
        if old_runtime is None:
            self.db.execute("INSERT INTO meta VALUES('runtime',?)", (runtime,))
        elif old_runtime[0] != runtime:
            self.db.close()
            raise ValueError("investigator runtime changed; explicit versioned migration required")
        prior = self.db.execute("SELECT value FROM meta WHERE key='sources'").fetchone()
        if prior is None:
            self.db.execute("INSERT INTO meta VALUES('sources',?)", (encoded(sources or {}),))
        elif sources is not None and encoded(sources) != prior[0]:
            self.db.close()
            raise ValueError("source packet is immutable; open a new version to change it")
        self.sources = json.loads(self.db.execute("SELECT value FROM meta WHERE key='sources'").fetchone()[0])

    def close(self):
        self.db.close()

    def state(self, *, summary=False):
        state = self.campaign.state()
        if summary:
            return self._summary(state)
        return {**state, **self._feedback_state(state), "compute_resources": resource_policy(), "investigator_models": self.campaign.models(),
                "staged_sources": sorted(p.stem for p in self.staged.glob("*.py")),
                "source_packet_sha256": signature(self.sources),
                "released_artifacts": self.campaign.artifacts(),
                "computation_artifacts": self._computation_artifacts(),
                "decision_index": self._decision_index(),
                "scientific_branches": self._branches()}

    @property
    def feedback_enabled(self):
        return self.sources.get("task", {}).get("feedback_profile") == FEEDBACK_PROFILE

    def inference_resources(self):
        """Owner-published public accounting; never interpret missing billing as zero."""
        path = self.directory / "resource_status.json"
        try:
            descriptor = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
        except FileNotFoundError:
            return {"status": "unavailable", "request_commitment_allowed": False,
                    "reason": "live inference accounting has not been published"}
        with os.fdopen(descriptor, "rb") as handle:
            info = os.fstat(handle.fileno())
            if not stat.S_ISREG(info.st_mode) or info.st_size > 65536:
                raise ValueError("public inference accounting must be a bounded regular file")
            result = json.loads(handle.read(65537))
        if not isinstance(result, dict) or type(result.get("request_commitment_allowed")) is not bool:
            raise ValueError("public inference accounting requires explicit request_commitment_allowed")
        encoded(result)
        return result

    def feedback_summary(self):
        """Compact deterministic release feedback, callable by the existing driver."""
        if not self.feedback_enabled:
            return {}
        state = self.campaign.state()
        summaries = []
        for request in state["requests"][-5:]:
            if not request["released_delivery_ids"]:
                continue
            report = public_diagnostics(self.campaign.request(request["request_id"]), state["evidence"])
            issues = []
            for target in report["targets"]:
                for observation in target["observations"]:
                    for key in ("stage_check", "definition_check", "magnetic_context_check"):
                        if observation.get(key, {}).get("reason"):
                            issues.append({"specimen_id": target["specimen_id"], "quantity": target["quantity"],
                                           "reason": observation[key]["reason"]})
                    if observation.get("unit_compatible") is False:
                        issues.append({"specimen_id": target["specimen_id"], "quantity": target["quantity"], "reason": "unit_mismatch"})
            summaries.append({"request_id": report["request_id"], "counts": report["counts"],
                "genealogy": report["genealogy"], "compatibility_issues": issues[:12],
                "declared_uncertainty_semantics": sorted({str(t["uncertainty_semantics"])
                    for t in report["targets"] if t["quantity"] in numerical_units(request["request"])}),
                "gaussian_calibration_claim": False,
                "compatibility_issue_count": len(issues), "diagnostic_errors": report["diagnostic_errors"],
                "comparisons": [{"specimen_id": target["specimen_id"], "quantity": target["quantity"],
                    "predicted": row["predicted"], "observed": row["observed"], "error": row["error"], "unit": row["unit"]}
                    for target in report["targets"] for row in target.get("residuals", [])][:12],
                "retrieval": "inspect_feedback(request_id=...) for every target, declared uncertainty and raw reduction references"})
        return {"profile": FEEDBACK_PROFILE, "recent_released_requests": summaries,
                "diagnostic_scope": "descriptive public comparisons, not a scientific conclusion or reward"}

    def _feedback_state(self, state):
        if not self.feedback_enabled:
            return {}
        histories = state.get("specimen_histories", [])
        manufactured = [h for h in histories if h["reported_manufactured"]]
        available = [h for h in manufactured if h["specimen_available"]]
        return {"inference_resources": self.inference_resources(),
                "physical_measurement_capabilities": physical_measurement_capabilities(),
                "physical_material_plan": self.sources.get("task", {}).get("physical_material_plan", {}),
                "virtual_material_inventory": {
                    "requested_bodies": len(histories), "reported_manufactured_bodies": len(manufactured),
                    "reported_available_bodies": len(available),
                    "known_remaining_body_mass_g": sum(h["remaining_mass_g"] for h in available
                        if h["remaining_mass_g"] is not None),
                    "bodies_with_unknown_remaining_mass": sum(h["remaining_mass_g"] is None for h in available),
                    "limits": "Released virtual bodies only; not subtraction from actual RPI powder stock. Losses and physical usable stock remain as declared in physical_material_plan."},
                "live_feedback": self.feedback_summary()}

    def _decision_records(self):
        # Only public decisions, never private receipts, unreviewed deliveries or
        # migration filesystem manifests. The append-only event is the original.
        return [{"sequence": event["sequence"], "call_id": event["data"].get("call_id"),
                 **event["data"]["result"]}
                for event in self.campaign.history() if event["kind"] == "decision"]

    def _decision_index(self):
        return [{"sequence": record["sequence"], "decision": record["decision"],
                 "recorded_at": record["recorded_at"], "model_id": record["model_id"],
                 "sha256": signature(record),
                 "retrieval_section": "decision:" + str(record["sequence"])}
                for record in self._decision_records()]

    def _summary(self, state):
        # Summary never includes source text, frozen forecast arrays or raw rows.
        # The full scientific payload and durable records remain unchanged.
        return {"campaign_id": state["campaign_id"],
                **self._feedback_state(state),
                "compute_resources": resource_policy(),
                "active_model_id": state["active_model_id"],
                "resources": {**state["resources"],
                    "preserved_computation_receipts": sum(1 for p in self.receipts.glob("*/receipt.json"))},
                "physical_execution": state["physical_execution"],
                "last_decision": {k: (v[:1500] if isinstance(v, str) else v)
                                  for k, v in (state["last_decision"] or {}).items()},
                "request_count": len(state["requests"]),
                "recent_requests": [{k: row.get(k) for k in
                    ("request_id", "status", "model_id", "execution_status", "released_delivery_ids")}
                    for row in state["requests"][-10:]],
                "evidence_count": len(state["evidence"]),
                "evidence_sha256": signature(state["evidence"]),
                "model_count": len(self.campaign.models()),
                "staged_sources": sorted(p.stem for p in self.staged.glob("*.py"))[-10:],
                "source_packet_sha256": signature(self.sources),
                "source_keys": sorted(self.sources),
                "decision_count": len(self._decision_index()),
                "recent_decisions": self._decision_index()[-10:],
                "computation_artifact_count": len(self._computation_artifacts()),
                "recent_computation_artifacts": self._computation_artifacts()[-5:],
                "scientific_branch_count": len(self._branches()),
                "recent_scientific_branches": [{k: row[k] for k in
                    ("branch_id", "status", "source_sha256", "evidence_sha256", "execution_id")}
                    for row in self._branches()[-5:]],
                "sections": [*state, *(self._feedback_state(state) if self.feedback_enabled else {}), "compute_resources", "investigator_models", "staged_sources", "released_artifacts", "computation_artifacts", "scientific_branches", "decision_index"],
                "retrieval": "inspect_state(section=...) returns bounded JSON text pages; use next_offset until null. decision_index lists original public decisions and owner updates; decision:SEQUENCE retrieves an original even after later decisions. compute receives full state/evidence/sources and a compact decision index."}

    @staticmethod
    def _page(value, args):
        offset, limit = args.get("offset", 0), args.get("limit", 8000)
        if type(offset) is not int or offset < 0 or type(limit) is not int or not 1 <= limit <= 16000:
            raise ValueError("offset must be nonnegative and limit must be 1..16000 characters")
        content = encoded(value)
        return {"encoding": "json", "sha256": signature(value), "offset": offset,
                "total_characters": len(content), "content": content[offset:offset + limit],
                "next_offset": offset + limit if offset + limit < len(content) else None}

    def _branches(self, branch_id=None):
        records = []
        for row in self.db.execute("SELECT id,intent,result FROM calls WHERE name='compute' AND intent IS NOT NULL ORDER BY rowid"):
            intent = json.loads(row["intent"])
            branch = intent.get("branch")
            if branch is None or (branch_id is not None and branch["branch_id"] != branch_id):
                continue
            result = json.loads(row["result"]) if row["result"] else None
            item = {**branch, "call_id": row["id"],
                    "status": "completed" if result else ("execution_unknown" if intent.get("execution_started") else "prepared"),
                    "execution_id": result.get("execution_id") if result else None,
                    "result_sha256": (result.get("scientific_result_sha256") or signature(result["result"])) if result else None}
            if branch_id is not None:
                item["computation"] = result
            records.append(item)
        return records

    def _model_source(self, digest):
        if not isinstance(digest, str) or len(digest) != 64 or any(c not in "0123456789abcdef" for c in digest):
            raise ValueError("invalid source digest")
        if (self.staged / (digest + ".py")).exists():
            return self._source(digest)
        for model in self.campaign.models():
            if model["source_sha256"] == digest:
                source = model["source"]
                if hashlib.sha256(source.encode()).hexdigest() != digest:
                    raise ValueError("adopted model integrity failure")
                return source
        raise ValueError("unknown staged or adopted model source")

    @staticmethod
    def _artifact_digest(digest):
        if not isinstance(digest, str) or len(digest) != 64 or any(c not in "0123456789abcdef" for c in digest):
            raise ValueError("invalid artifact digest")
        return digest

    def _computation_artifacts(self):
        """Index accepted compute exports; failed/orphan receipts grant no access.

        Bytes are streamed and verified on read/reuse, never injected in context.
        """
        records = []
        for row in self.db.execute("SELECT id,result FROM calls WHERE name='compute' AND result IS NOT NULL ORDER BY rowid"):
            result = json.loads(row["result"])
            if result.get("status") != "ok":
                continue
            exports = list(result.get("exported_artifacts", []))
            if result.get("result_artifact"):
                exports.append(result["result_artifact"])
            if not exports:
                continue
            execution_id = result.get("execution_id")
            if not isinstance(execution_id, str) or PurePosixPath(execution_id).parts != (execution_id,) or execution_id in {".", ".."}:
                raise ValueError("invalid computation artifact execution identity")
            for artifact in exports:
                digest = self._artifact_digest(artifact.get("sha256"))
                relative = PurePosixPath(artifact.get("receipt_relative_path", ""))
                is_result = artifact is result.get("result_artifact") and relative.parts == ("result.json",)
                if not is_result and (len(relative.parts) != 2 or relative.parts[0] != "exported" or relative.parts[1] in {".", ".."}):
                    raise ValueError("invalid computation artifact receipt path")
                size = artifact.get("bytes")
                if type(size) is not int or size < 0:
                    raise ValueError("invalid computation artifact size")
                records.append({"sha256": digest, "size_bytes": size,
                                "path": artifact.get("path"),
                                "receipt_relative_path": relative.as_posix(),
                                "execution_id": execution_id, "call_id": row["id"],
                                "evidence_class": "investigator_computation",
                                "integrity": "complete hash verified on read or reuse"})
        return records

    def _compute_result_delivery(self, result):
        """Keep the exact numerical result in its receipt, with bounded tool delivery.

        The executor's result-file hash establishes an additional computational
        artifact. Legacy injected executors without that receipt contract retain
        their existing small-result interface.
        """
        scientific_result = result["result"]
        large = len(encoded(scientific_result)) > 16000
        digest = result.get("hashes", {}).get("result_sha256")
        if digest is None:
            if large:
                raise ValueError("large compute RESULT requires a durable executor result.json receipt")
            return result
        self._artifact_digest(digest)
        execution_id = result.get("execution_id")
        if not isinstance(execution_id, str) or PurePosixPath(execution_id).parts != (execution_id,) or execution_id in {".", ".."}:
            raise ValueError("invalid computation result execution identity")
        directory_fd = os.open(self.receipts / execution_id, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
        try:
            file_fd = os.open("result.json", os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=directory_fd)
        finally:
            os.close(directory_fd)
        with os.fdopen(file_fd, "rb") as stream:
            info = os.fstat(stream.fileno())
            if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
                raise ValueError("invalid computation result artifact file")
            hasher, size = hashlib.sha256(), 0
            for chunk in iter(lambda: stream.read(1024 * 1024), b""):
                hasher.update(chunk)
                size += len(chunk)
            if size != info.st_size or hasher.hexdigest() != digest:
                raise ValueError("computation result artifact integrity failure")
        artifact = {"path": "result.json", "receipt_relative_path": "result.json",
                    "sha256": digest, "bytes": size}
        result = {**result, "result_artifact": artifact}
        if large:
            keys = list(scientific_result) if isinstance(scientific_result, dict) else []
            result.update(scientific_result_sha256=signature(scientific_result), result={
                "delivery": "durable_artifact", "execution_id": execution_id,
                "artifact_sha256": digest, "artifact_bytes": size,
                "top_level_keys": [str(key)[:128] for key in keys[:50]],
                "top_level_key_count": len(keys),
                "retrieval": "read_artifact(sha256=artifact_sha256, offset=0, limit_bytes=16384); follow next_offset. Reuse with compute artifact_sha256s at /workspace/raw/SHA256.",
            })
        return result

    def _artifact_binding(self, digest):
        self._artifact_digest(digest)
        released = next((a for a in self.campaign.artifacts() if a["sha256"] == digest), None)
        if released is not None:
            return self.campaign.store.blobs, (digest,), {
                "sha256": digest, "size_bytes": released["size_bytes"],
                "evidence_class": "released_raw_artifact", "delivery_id": released["delivery_id"],
            }
        computed = next((a for a in self._computation_artifacts() if a["sha256"] == digest), None)
        if computed is not None:
            parts = (computed["execution_id"], *PurePosixPath(computed["receipt_relative_path"]).parts)
            return self.receipts, parts, computed
        raise ValueError("artifact is neither released evidence nor a completed computation export")

    def _stream_artifact(self, digest, *, destination=None, offset=0, limit=0):
        """Confined streaming copy/read with exact length, hash and no-symlink checks."""
        root, parts, metadata = self._artifact_binding(digest)
        try:
            directory_fd = os.open(root, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
        except OSError as error:
            raise ValueError("artifact directory is missing, linked or inaccessible") from error
        try:
            for part in parts[:-1]:
                next_fd = os.open(part, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW,
                                  dir_fd=directory_fd)
                os.close(directory_fd)
                directory_fd = next_fd
            file_fd = os.open(parts[-1], os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK,
                              dir_fd=directory_fd)
        except OSError as error:
            raise ValueError("artifact file is missing, linked or inaccessible") from error
        finally:
            os.close(directory_fd)
        selected = bytearray()
        with os.fdopen(file_fd, "rb") as stream:
            info = os.fstat(stream.fileno())
            if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1 or info.st_size != metadata["size_bytes"]:
                raise ValueError("artifact file changed or is not a regular file without hard links")
            output = destination.open("xb") if destination is not None else None
            try:
                length, hasher = 0, hashlib.sha256()
                while block := stream.read(1024 * 1024):
                    start = length
                    length += len(block)
                    if length > metadata["size_bytes"]:
                        raise ValueError("artifact grew during read")
                    hasher.update(block)
                    if output is not None:
                        output.write(block)
                    lo, hi = max(offset, start), min(offset + limit, length)
                    if lo < hi:
                        selected.extend(block[lo - start:hi - start])
                if length != metadata["size_bytes"] or hasher.hexdigest() != digest:
                    raise ValueError("artifact integrity mismatch")
            finally:
                if output is not None:
                    output.close()
        return bytes(selected), metadata

    def _payload(self, request=None, inputs=None):
        state = self.campaign.state()
        state.update(self._feedback_state(state))
        evidence = state.pop("evidence", [])
        state["computation_artifacts"] = self._computation_artifacts()
        state["decision_index"] = self._decision_index()
        return {"request": request, "evidence": evidence,
                "investigation_state": state, "sources": self.sources,
                "inputs": inputs or {}}

    def _execute(self, source, payload, code=None, artifact_sha256s=()):
        # Only frozen public inputs are mounted, never the owner Campaign directory.
        with tempfile.TemporaryDirectory(prefix="ndfeb-investigator-") as temporary:
            workspace = Path(temporary)
            (workspace / "model.py").write_text(source)
            bound = {}
            legacy = resource_policy()["profile"] == "legacy-bounded-v1"
            # These fields come from the frozen owner-created computation
            # payload, never from investigator-supplied input or a workspace
            # manifest. Bind the exact complete JSON to the executor's existing
            # public-data path; the request, inputs and sources retain its 8 MiB
            # input guard. Public JSON and selected raw files share one budget.
            total = len((encoded(payload.get("sources", {})) + "\n").encode())
            public_fields = {}
            for field, filename in (("evidence", "released_evidence.json"),
                                    ("investigation_state", "investigation_state.json")):
                if field not in payload:
                    continue
                data = (encoded(payload[field]) + "\n").encode()
                total += len(data)
                if legacy and total > PUBLIC_SNAPSHOT_BYTES:
                    raise ValueError("public data snapshot exceeds 64 MiB")
                (workspace / filename).write_bytes(data)
                digest = hashlib.sha256(data).hexdigest()
                bound[filename] = digest
                public_fields[field] = digest
            if legacy and len(artifact_sha256s) > 8:
                raise ValueError("at most eight released artifacts per computation")
            if artifact_sha256s:
                (workspace / "raw").mkdir()
            for digest in artifact_sha256s:
                _, _, metadata = self._artifact_binding(digest)
                total += metadata["size_bytes"]
                if legacy and total > PUBLIC_SNAPSHOT_BYTES:
                    raise ValueError("public data snapshot exceeds 64 MiB")
                self._stream_artifact(digest, destination=workspace / "raw" / digest)
                bound["raw/" + digest] = digest
            result = self.executor(workspace, payload, self.receipts, code=code, trusted_files=bound,
                                   trusted_payload_fields=public_fields)
        if result.get("status") != "ok":
            raise ScientificExecutionError(result)
        return {key: value for key, value in result.items() if key != "receipt_dir"}

    def _forecast(self, source, request, artifact_sha256s=()):
        payload = self._payload(request=request)
        if artifact_sha256s:
            payload["model_artifact_sha256s"] = list(artifact_sha256s)
        a = self._execute(source, payload, artifact_sha256s=artifact_sha256s)
        b = self._execute(source, payload, artifact_sha256s=artifact_sha256s)
        for result in (a, b):
            validate_forecast(result["result"], request)
            check_physical_forecast_source(
                hashlib.sha256(source.encode()).hexdigest(), request, result["result"]
            )
        if encoded(a["result"]) != encoded(b["result"]):
            raise ValueError("forecast is not deterministic under identical public inputs")
        return {"forecast": a["result"], "evidence_ids": [e["evidence_id"] for e in payload["evidence"]],
                "input_sha256": signature(payload), "executions": [a["execution_id"], b["execution_id"]]}

    def _source(self, digest):
        if not isinstance(digest, str) or len(digest) != 64 or any(c not in "0123456789abcdef" for c in digest):
            raise ValueError("invalid source digest")
        source = (self.staged / (digest + ".py")).read_text()
        if hashlib.sha256(source.encode()).hexdigest() != digest:
            raise ValueError("staged model integrity failure")
        return source

    def call(self, call_id, name, arguments):
        if not isinstance(call_id, str) or not call_id or len(call_id) > 256:
            raise ValueError("bounded nonempty call_id required")
        spec = next((spec for spec in TOOLS if spec["name"] == name), None)
        if spec is None:
            raise ValueError("tool unavailable; operator authority is not an agent tool")
        if name in {"preview_request", "inspect_feedback"} and not self.feedback_enabled:
            raise ValueError("tool requires a fresh dense-public-v1 source profile")
        allowed = spec["parameters"]["properties"]
        if not isinstance(arguments, dict) or set(arguments) - set(allowed):
            raise ValueError("unexpected tool arguments")
        if not set(spec["parameters"]["required"]).issubset(arguments):
            raise ValueError("missing required arguments")
        key = signature({"name": name, "arguments": arguments})
        previous = self.db.execute("SELECT * FROM calls WHERE id=?", (call_id,)).fetchone()
        if previous and previous["signature"] != key:
            raise ValueError("call ID reused with changed arguments")
        if previous and previous["result"]:
            return json.loads(previous["result"])
        if previous is None:
            self.db.execute("INSERT INTO calls VALUES(?,?,?,?,NULL,NULL)", (call_id, key, name, encoded(arguments)))
        intent = json.loads(previous["intent"]) if previous and previous["intent"] else None
        if intent is None:
            intent = self._prepare(name, arguments)
            self.db.execute("UPDATE calls SET intent=? WHERE id=?", (encoded(intent), call_id))
        result = self._apply(call_id, name, arguments, intent)
        self.db.execute("UPDATE calls SET result=? WHERE id=?", (encoded(result), call_id))
        return result

    def _selected_artifacts(self, artifacts):
        available = {row["sha256"] for row in self.campaign.artifacts()} | {
            row["sha256"] for row in self._computation_artifacts()}
        if not isinstance(artifacts, list) or any(not isinstance(digest, str) or digest not in available for digest in artifacts):
            raise ValueError("computation artifacts must be released evidence or completed computation exports at the frozen cutoff")
        if len(artifacts) != len(set(artifacts)):
            raise ValueError("artifact_sha256s must contain distinct artifact hashes")
        if resource_policy()["profile"] == "legacy-bounded-v1" and len(artifacts) > 8:
            raise ValueError("at most eight artifacts per computation in legacy-bounded-v1")
        return list(artifacts)

    def _prepare_computation(self, args):
        if not isinstance(args["code"], str):
            raise TypeError("code must be text")
        payload = self._payload(inputs=args.get("inputs"))
        artifacts = self._selected_artifacts(args.get("artifact_sha256s", []))
        intent = {"payload": payload, "source": "", "artifact_sha256s": artifacts}
        if "branch" in args:
            supplied = args["branch"]
            if not isinstance(supplied, dict) or set(supplied) - set(BRANCH["properties"]) or not set(BRANCH["required"]).issubset(supplied):
                raise ValueError("branch requires branch_id, source_sha256 and assumptions")
            identifier = supplied["branch_id"]
            if not isinstance(identifier, str) or not identifier.strip() or len(identifier) > 128:
                raise ValueError("branch_id must be nonempty and at most 128 characters")
            if self._branches(identifier):
                raise ValueError("branch_id already has a frozen computation; use a new branch_id")
            if not isinstance(supplied["assumptions"], dict) or not supplied["assumptions"] or len(encoded(supplied["assumptions"]).encode()) > 16000:
                raise ValueError("branch assumptions must be a nonempty JSON object of at most 16000 bytes")
            source = self._model_source(supplied["source_sha256"])
            parent_id = supplied.get("parent_model_id", payload["investigation_state"]["active_model_id"])
            parent = self.campaign.model(parent_id) if parent_id is not None else None
            branch = {"branch_id": identifier, "source_sha256": supplied["source_sha256"],
                      "parent_model_id": parent_id,
                      "parent_source_sha256": parent["source_sha256"] if parent else None,
                      "assumptions": supplied["assumptions"], "frozen_at": now(),
                      "evidence_ids": [row["evidence_id"] for row in payload["evidence"]],
                      "evidence_sha256": signature(payload["evidence"]),
                      "source_packet_sha256": signature(payload["sources"]),
                      "evidence_class": "conditional_counterfactual_computation",
                      "promotion": "none; adoption and experimental request remain separate decisions"}
            payload["branch"] = branch
            intent.update(source=source, branch=branch)
        # Encoding detaches mutable caller objects before durable intent commit.
        return json.loads(encoded(intent))

    def _prepare(self, name, args):
        if name == "preview_request":
            return {"preview": self._preview(args)}
        if name == "compute":
            with self.campaign.store.transaction():
                return self._prepare_computation(args)
        if name == "record_decision":
            state = self.campaign.state()
            if self.feedback_enabled and args["decision"] == "stop":
                pending = [r["request_id"] for r in state["requests"]
                           if r["request"]["origin"] == "synthetic" and r["status"]
                           not in {"complete", "execution_failed", "rejected"}]
                if pending:
                    raise ValueError("stop cannot close an episode with pending returns: " + ", ".join(pending)
                                     + "; wait for release or resolve execution status, then interpret returns")
            return {"context": {"model_id": state["active_model_id"],
                                "evidence_sha256": signature(state["evidence"])}}
        if name == "adopt_model":
            source = self._source(args["source_sha256"])
            artifacts = self._selected_artifacts(args.get("artifact_sha256s", []))
            return {"source": source, **({"artifact_sha256s": artifacts} if artifacts else {}),
                    **self._forecast(source, args["test_request"], artifacts)}
        if name == "submit_batch":
            if self.feedback_enabled and not self.campaign.store.has("request", args["request_id"]):
                resources = self.inference_resources()
                if (self.sources.get("task", {}).get("require_resource_status") or resources.get("status") != "unavailable") and not resources["request_commitment_allowed"]:
                    raise ValueError("new experiment commitment would consume reserved interpretation capacity; "
                                     "inspect inference_resources, interpret released evidence and record a supported decision. "
                                     "This guard is a resource limit, not a scientific conclusion")
            # Reject malformed identity/condition records before paying for the
            # two numerical forecast executions. The operator repeats validation
            # at commit; immutable state and crash-replay authority remain there.
            request = request_record(args["request"])
            if self.feedback_enabled:
                preview = request_preview(request, self.campaign.state(), self.sources)
                if preview["errors"]:
                    raise ValueError("request preview found contract errors: " + "; ".join(preview["errors"]))
            if request.get("operation", "manufacture") != "manufacture":
                # Bind already-public history before prediction. This is data
                # delivery, not an owner-supplied scientific inference.
                for specimen in request["specimens"]:
                    history = self.campaign.specimen_history(specimen["specimen_id"])
                    specimen.setdefault("prior_processing_conditions", history["processing_history_conditions"])
                    if history["remaining_mass_g"] is not None:
                        specimen.setdefault("remaining_mass_g", history["remaining_mass_g"])
                        specimen["conditions"].setdefault("mass_g", history["remaining_mass_g"])
            models = self.campaign.models()
            state = self.campaign.state()
            active = state.get("active_model_id") or state.get("active_model")
            if isinstance(active, dict):
                active = active.get("model_id")
            model = next((m for m in models if m["model_id"] == active), None)
            if model is None:
                raise ValueError("adopt an executable model before proposing a batch")
            artifacts = self._selected_artifacts(model.get("artifact_sha256s", []))
            return {"model_id": active, "bound_request": request,
                    **self._forecast(model["source"], request, artifacts)}
        return {}

    def _preview(self, args):
        state = self.campaign.state()
        request = json.loads(encoded(args["request"]))
        result = request_preview(request, state, self.sources)
        result.update(status="read_only_preview", campaign_mutated=False, experiment_executed=False,
                      provisional_prediction=True, inference_resources=self.inference_resources())
        prediction = args.get("prediction")
        if prediction is not None and "source_sha256" in args:
            result["errors"].append("provide prediction or source_sha256, not both")
        elif prediction is None and not result["errors"]:
            for specimen in request["specimens"]:
                if request.get("operation", "manufacture") != "manufacture":
                    history = self.campaign.specimen_history(specimen["specimen_id"])
                    specimen.setdefault("prior_processing_conditions", history["processing_history_conditions"])
                    if history["remaining_mass_g"] is not None:
                        specimen.setdefault("remaining_mass_g", history["remaining_mass_g"])
                        specimen["conditions"].setdefault("mass_g", history["remaining_mass_g"])
            model = self.campaign.model(state["active_model_id"]) if state["active_model_id"] else None
            source = self._model_source(args["source_sha256"]) if "source_sha256" in args else model["source"] if model else None
            if source is not None:
                artifacts = model.get("artifact_sha256s", []) if model and model["source"] == source else []
                payload = self._payload(request=request)
                if artifacts:
                    payload["model_artifact_sha256s"] = artifacts
                try:
                    first = self._execute(source, payload, artifact_sha256s=artifacts)
                    second = self._execute(source, payload, artifact_sha256s=artifacts)
                    prediction = first["result"]
                    result["calculation_receipts"] = [first["execution_id"], second["execution_id"]]
                    result["source_sha256"] = hashlib.sha256(source.encode()).hexdigest()
                    result["input_sha256"] = signature(payload)
                    if encoded(prediction) != encoded(second["result"]):
                        result["errors"].append("forecast differs under identical public inputs")
                except ScientificExecutionError as exc:
                    result["errors"].append("model calculation failed; this is not experimental evidence")
                    result["calculation_error"] = exc.public_details
            else:
                result["notes"].append("No active or selected model: supply prediction or source_sha256 to preview forecast")
        if prediction is not None:
            checks = forecast_issues(prediction, request)
            result["prediction"] = prediction
            result["forecast_targets"] = checks["targets"]
            result["errors"].extend(checks["errors"])
            result["notes"].extend(checks["notes"])
        result["contract_ready"] = not result["errors"] and prediction is not None
        result["limits"] = ["Preview is not a commitment, plant evaluation, physical validation or authorization",
                            "Only explicit readbacks establish delivered controls; unknown cooling rates remain unknown",
                            "A valid contract does not establish scientific support"]
        return result

    def _apply(self, call_id, name, args, intent):
        if name == "preview_request":
            return intent["preview"]
        if name == "inspect_feedback":
            if "request_id" not in args:
                return self.feedback_summary()
            record = self.campaign.request(args["request_id"])
            return self._page(public_diagnostics(record, self.campaign.evidence()), args)
        if name == "inspect_state":
            section = args.get("section", "summary")
            if section == "summary":
                return self.state(summary=True)
            if isinstance(section, str) and section.startswith("branch:"):
                records = self._branches(section.removeprefix("branch:"))
                if not records:
                    raise ValueError("unknown scientific branch")
                return {"section": section, **self._page(records[0], args)}
            if isinstance(section, str) and section.startswith("decision:"):
                records = [r for r in self._decision_records()
                           if str(r["sequence"]) == section.removeprefix("decision:")]
                if not records:
                    raise ValueError("unknown public decision")
                return {"section": section, **self._page(records[0], args)}
            state = self.state()
            if section not in state:
                raise ValueError("unknown public state section")
            return {"section": section, **self._page(state[section], args)}
        if name == "read_evidence":
            return self._page(self.campaign.evidence(), args)
        if name == "read_sources":
            value = self.sources if "key" not in args else self.sources[args["key"]]
            return self._page(value, args)
        if name == "read_model":
            return {"source_sha256": args["source_sha256"], **self._page(self._model_source(args["source_sha256"]), args)}
        if name == "read_artifact":
            offset, limit = args.get("offset", 0), args.get("limit_bytes", 16384)
            if type(offset) is not int or offset < 0 or type(limit) is not int or not 1 <= limit <= 1048576:
                raise ValueError("artifact offset must be nonnegative bytes; limit_bytes must be 1..1048576")
            data, metadata = self._stream_artifact(args["sha256"], offset=offset, limit=limit)
            page = {"sha256": args["sha256"], "offset": offset,
                    "total_bytes": metadata["size_bytes"], "evidence_class": metadata["evidence_class"],
                    "next_offset": offset + len(data) if offset + len(data) < metadata["size_bytes"] else None}
            try:
                return {**page, "encoding": "utf8", "content": data.decode("utf8")}
            except UnicodeDecodeError:
                return {**page, "encoding": "base64", "content": base64.b64encode(data).decode()}
        if name == "compute":
            if "payload" not in intent:
                raise ValueError("legacy interrupted computation has no frozen input; start a new explicit call")
            if intent.get("execution_started"):
                raise ValueError("previous computation started but no committed result exists; execution outcome is unknown. Inspect preserved receipts; use a new call and a new branch_id rather than rerunning this call")
            started = {**intent, "execution_started": now()}
            changed = self.db.execute("UPDATE calls SET intent=? WHERE id=? AND result IS NULL AND intent=?",
                                      (encoded(started), call_id, encoded(intent)))
            if changed.rowcount != 1:
                raise ValueError("computation intent changed or is not durable; no execution started")
            # FULL-synchronous SQLite commit precedes isolated execution. A crash
            # after this point cannot silently replace a stochastic result on replay.
            result = self._execute(intent["source"], intent["payload"], code=args["code"],
                                   artifact_sha256s=intent["artifact_sha256s"])
            result = self._compute_result_delivery(result)
            if "branch" in intent:
                result = {**result, "branch": intent["branch"]}
            return result
        if name == "stage_model":
            source = args["source"]
            if not isinstance(source, str) or len(source.encode()) > 4 * 1024 * 1024:
                raise ValueError("model source must be at most 4 MiB")
            digest = hashlib.sha256(source.encode()).hexdigest()
            destination = self.staged / (digest + ".py")
            if destination.exists() and destination.read_text() != source:
                raise ValueError("model source digest collision")
            if not destination.exists():
                with destination.open("x") as file:
                    file.write(source)
            return {"status": "staged", "source_sha256": digest}
        if name == "adopt_model":
            adopted = self.campaign.adopt_model(intent["source"], args["rationale"], intent["evidence_ids"],
                                                call_id=call_id, expected_evidence_ids=intent["evidence_ids"],
                                                artifact_sha256s=intent.get("artifact_sha256s"))
            return {"status": "adopted", **adopted, "verification": {k: v for k, v in intent.items() if k != "source"}}
        if name == "submit_batch":
            return self.campaign.submit(intent.get("bound_request", args["request"]), intent["forecast"], args["request_id"], call_id=call_id,
                                        expected_model_id=intent["model_id"], expected_evidence_ids=intent["evidence_ids"])
        if name == "record_decision":
            return self.campaign.record_decision(args["decision"], args["rationale"], call_id=call_id,
                                                 expected_context=intent["context"])
        if name == "compact_context":
            return {"status": "requested", "notes": args["notes"], "route": "native_pi_compaction"}
        raise AssertionError("unhandled tool")
